package com.jobpilot.personalizedmatching;

import java.time.Instant;
import java.util.List;
import java.math.BigDecimal;

/** Neutral facts. A requirement's quote is copied from source, never generated by a model. */
public record VacancyFacts(String title,String description,String location,String workFormat,String employmentType,
        String industry,Instant publishedAt,Instant deadline,String status,String provenance,
        List<Requirement> requirements,Salary salary) {
    public enum Modality { REQUIRED, PREFERRED, UNSPECIFIED }
    public record Requirement(String kind,String value,String level,Modality modality,String evidence) {
        public Requirement {modality=modality==null?Modality.UNSPECIFIED:modality;}
        public boolean mandatory(){return modality==Modality.REQUIRED;}
    }
    public record Salary(BigDecimal amount,String currency,String period,String basis) { }
    public VacancyFacts {
        // Historical jobs.status can contain owner workflow states; never expose those as shared facts.
        status="EXPIRED".equals(status)?"EXPIRED":"OPEN";
        requirements=List.copyOf(requirements);
    }
}
